missing_type.style.css:
body {
    font-family: Arial, sans-serif;
    background-color: #f4f4f9;
    color: #333;
    margin: 0;
    padding: 20px;
}

button {
    background-color: #007bff;
    color: white;
    border: none;
    padding: 10px 20px;
    cursor: pointer;
    font-size: 16px;
    margin-bottom: 20px;
}

button:focus {
    outline: none;
}

#cv-content {
    background-color: #fff;
    padding: 20px;
    border-radius: 5px;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}

#cv-content p {
    font-size: 16px;
    line-height: 1.6;
}

body.cv-large-text #cv-content p {
    font-size: 20px;
}

missing_type.script.js:
document.getElementById('cv-font-toggle').addEventListener('click', function() {
    const cvContent = document.getElementById('cv-content');
    const isLargeText = this.getAttribute('aria-pressed') === 'true';

    if (isLargeText) {
        document.body.classList.remove('cv-large-text');
        this.setAttribute('aria-pressed', 'false');
    } else {
        document.body.classList.add('cv-large-text');
        this.setAttribute('aria-pressed', 'true');
    }
});

